/* ===================== BÀI 24 · Lab bộ đếm sản phẩm mini ===================== */
/* Bài 24 · Lab bộ đếm sản phẩm mini (AMTS-EMB-001-M06-L04, MC51-024) — sinh bởi tools/author/mcu8051/l24.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR24=[{"label":"Ví dụ: Tăng số đếm BCD và hiện ra LED","code":"; Ví dụ 1: lớp trạng thái - tăng số đếm BCD, lớp ra - LED\n; 8 LED P1 hiện 2 chữ số BCD: nửa cao = chục, nửa thấp = đơn vị\n        ORG     0000H\n        MOV     30H,#09H                ; đang đếm 09\n        MOV     A,30H\n        ADD     A,#01H                  ; 09H + 1 = 0AH (nhị phân)\n        DA      A                       ; hiệu chỉnh thập phân: 10H\n        MOV     30H,A                   ; số đếm mới = 10\n        CPL     A                       ; LED tích cực mức thấp\n        MOV     P1,A\n        SJMP    $\n        END\n","note":"Bước qua ADD A,#01H: A = 0AH, AC = 0, CY = 0. DA A thấy nửa thấp A > 9 nên cộng 06H: A = 10H. LED hiện 0001 0000: chục = 1, đơn vị = 0. Đoán trước: nếu 30H = 99H thì sau DA A, A và CY bằng bao nhiêu? (00H, CY = 1.)","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: Tăng bằng INC, quên hiệu chỉnh BCD","code":"; Lỗi 2: tăng số đếm bằng INC, quên hiệu chỉnh thập phân\n; LED hiện 0AH - không phải một số BCD.\n        ORG     0000H\n        MOV     30H,#09H\n        INC     30H                     ; 0AH chứ không phải 10H\n        MOV     A,30H\n        CPL     A\n        MOV     P1,A\n        SJMP    $\n        END\n","note":"INC 30H cho 0AH: LED hiện 0000 1010 — không có chữ số thập phân nào là 10. Ví dụ 1 dùng ADD + DA A để được 10H.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Bộ đếm sản phẩm ba lớp","code":"; Ví dụ 3: bộ đếm sản phẩm - 3 lớp trong mỗi tick ~0,5 ms\n; Vào: lọc K1 (4 mẫu) -> sự kiện F0. Trạng thái: 30H. Ra: P1.\n        ORG     0000H\n        MOV     30H,#00H                ; trạng thái: số đếm BCD\n        MOV     R3,#04H                 ; lớp vào: K1 ổn định = nhả\n        MOV     R2,#4                   ; còn cần 4 mẫu khác\n        MOV     R7,#60                  ; 60 tick (khoảng 30 ms)\n        MOV     P1,#0FFH                ; lớp ra: hiện 00\nTICK:   MOV     R6,#240\n        DJNZ    R6,$                    ; chờ tới tick sau\n        CLR     F0                      ; ---- lớp vào ----\n        MOV     A,P3\n        ANL     A,#04H                  ; mẫu K1\n        XRL     A,R3\n        JZ      GIONG                   ; giống trạng thái ổn định\n        DJNZ    R2,DEM                  ; khác: chưa đủ 4 mẫu\n        MOV     A,R3\n        XRL     A,#04H\n        MOV     R3,A                    ; đổi trạng thái ổn định\n        JNZ     GIONG                   ; thành \"nhả\": không có sự kiện\n        SETB    F0                      ; thành \"bấm\": sự kiện nhấn\nGIONG:  MOV     R2,#4\nDEM:    JNB     F0,XUAT                 ; ---- lớp trạng thái ----\n        MOV     A,30H\n        ADD     A,#01H\n        DA      A\n        MOV     30H,A\nXUAT:   MOV     A,30H                   ; ---- lớp ra ----\n        CPL     A\n        MOV     P1,A\n        DJNZ    R7,TICK\n        SJMP    $\n        END\n","note":"Mỗi tick ≈ 0,5 ms: lớp vào lọc K1 (R3 trạng thái ổn định, R2 đếm mẫu), đặt F0 khi có sự kiện nhấn; lớp trạng thái cộng BCD vào 30H; lớp ra ghi P1. Đổi Tốc độ sang Nhanh rồi bấm K1 vài lần trong lúc chạy: mỗi lần bấm cộng đúng 1 dù có dội, giữ nút không cộng thêm.","dev":{"led":true,"btn":{"bounce":[100,300,600,1000]}},"fosc":12000000,"speed":"real"},{"label":"Ví dụ: Giữ K2 lâu để xóa số đếm","code":"; Ví dụ 4: giữ K2 đủ 20 tick (~10 ms, giả định) thì xóa\n; R4 = số tick K2 đã giữ liên tục; xóa đúng MỘT lần.\n        ORG     0000H\n        MOV     30H,#25H                ; đang có 25 sản phẩm\n        MOV     R4,#0\n        MOV     R7,#40                  ; 40 tick\nTICK:   MOV     R6,#240\n        DJNZ    R6,$\n        JB      P3.3,NHA                ; K2 nhả: xóa bộ đếm giữ\n        CJNE    R4,#20,GIU              ; chưa đủ 20: đếm tiếp\n        SJMP    XUAT                    ; đã xóa rồi: không làm lại\nGIU:    INC     R4\n        CJNE    R4,#20,XUAT\n        MOV     30H,#00H                ; vừa đủ 20 tick: xóa số đếm\n        SJMP    XUAT\nNHA:    MOV     R4,#0\nXUAT:   MOV     A,30H                   ; lớp ra\n        CPL     A\n        MOV     P1,A\n        DJNZ    R7,TICK\n        SJMP    $\n        END\n","note":"Bắt đầu với 25 sản phẩm (P1 = DAH). Giữ K2: R4 tăng mỗi tick, đủ 20 thì 30H = 00H và R4 dừng ở 20. Chạm K2 ngắn rồi nhả: R4 về 0, số đếm còn nguyên. Không bấm: 19 564 chu kỳ, P1 = DAH.","dev":{"led":true,"btn":true},"fosc":12000000,"speed":"real"},{"label":"Bẫy: DA A sau INC dùng cờ CY cũ","code":"; Bẫy 5: DA A sau INC A dùng cờ CY, AC còn sót lại\n; DA A chỉ có nghĩa ngay sau ADD hoặc ADDC.\n        ORG     0000H\n        MOV     A,#15H                  ; số đếm BCD 15\n        SETB    C                       ; CY = 1 sót lại từ phép so trước\n        INC     A                       ; 16H; INC không đổi CY, AC\n        DA      A                       ; CY = 1 -> cộng 60H: 76H!\n        MOV     30H,A\n        SJMP    $\n        END\n","note":"SETB C giả lập cờ nhớ còn sót từ một lệnh so sánh trước. INC A không đổi CY, nên DA A thấy CY = 1 và cộng 60H: 16H thành 76H. Thay INC A bằng ADD A,#01H (ADD tự xóa/đặt CY, AC) để DA A đúng.","dev":{"led":true},"fosc":12000000}];
const sim24=makeSim51(document.getElementById("m51-l24"),{id:"s24",presets:PR24,ram:256});
makeEx51(document.getElementById("ex-l24"),"l24",[{"t":"Tăng BCD có giới hạn 99","d":"<p>Ô <code>30H<\/code> chứa số sản phẩm dạng BCD đóng gói (00–99). Viết lớp trạng thái cho một sự kiện “có sản phẩm”: nếu <code>30H = 99H<\/code> thì giữ nguyên và ghi <code>31H = 01H<\/code> (báo đầy); ngược lại tăng <code>30H<\/code> thêm 1 theo BCD và ghi <code>31H = 00H<\/code>. Sau đó lớp ra hiện số đếm lên 8 LED: <code>P1<\/code> = NOT <code>30H<\/code> (LED sáng khi chân = 0). Một lệnh <code>SJMP $<\/code> ở cuối.<\/p><p>Ví dụ: <code>30H = 09H<\/code> → <code>30H = 10H<\/code>, <code>31H = 00H<\/code>, <code>P1 = EFH<\/code>.<\/p>","start":"        ORG     0000H\n        INC     30H                     ; tăng số đếm\n        MOV     31H,#00H\n        MOV     A,30H\n        CPL     A\n        MOV     P1,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":9,"0x31":85}},"expect":{"iram":{"0x30":16,"0x31":0},"ports":{"P1":239}}},{"setup":{"iram":{"0x30":0,"0x31":85}},"expect":{"iram":{"0x30":1,"0x31":0},"ports":{"P1":254}}},{"setup":{"iram":{"0x30":25,"0x31":85}},"expect":{"iram":{"0x30":32,"0x31":0},"ports":{"P1":223}}},{"setup":{"iram":{"0x30":152,"0x31":85}},"expect":{"iram":{"0x30":153,"0x31":0},"ports":{"P1":102}}},{"setup":{"iram":{"0x30":153,"0x31":85}},"expect":{"iram":{"0x30":153,"0x31":1},"ports":{"P1":102}}},{"setup":{"iram":{"0x30":69,"0x31":85}},"expect":{"iram":{"0x30":70,"0x31":0},"ports":{"P1":185}}}]},"hints":["Tăng BCD: cộng bằng ADD A,#01H rồi hiệu chỉnh thập phân ngay sau đó. INC không đặt cờ AC nên không đi với DA A.","So với 99H bằng CJNE A,#99H,nhãn trước khi cộng.","Ghi trước cờ “đầy”, chỉ nhánh chưa đầy ghi đè; hai nhánh gặp nhau ở đoạn xuất LED."],"why":"BCD đóng gói cho phép hiện thẳng hai chữ số lên LED hoặc LED 7 đoạn. DA A hiệu chỉnh tổng của ADD/ADDC dựa vào cờ AC và CY; sau INC thì các cờ đó không phản ánh phép cộng (ví dụ 5). Giới hạn 99 tránh quay vòng về 00 âm thầm."},{"t":"Giữ nút lâu để xóa, chỉ xóa một lần","d":"<p>Mỗi tick gọi một lần. Ô <code>32H<\/code> = số tick K2 (chân <code>P3.3<\/code>, bấm = 0) đã được giữ liên tục, <code>30H<\/code> = số đếm. Quy tắc: nếu K2 nhả thì <code>32H = 00H<\/code>. Nếu K2 đang bấm: khi <code>32H<\/code> &lt; 20 (14H) thì tăng <code>32H<\/code>, và nếu vừa tăng lên đúng 20 thì xóa <code>30H = 00H<\/code>; khi <code>32H<\/code> đã bằng 20 thì không làm gì (không xóa lại sản phẩm đếm được trong lúc vẫn giữ). Một lệnh <code>SJMP $<\/code> ở cuối.<\/p><p>Ví dụ: <code>32H = 13H<\/code>, <code>30H = 37H<\/code>, K2 bấm → <code>32H = 14H<\/code>, <code>30H = 00H<\/code>.<\/p>","start":"        ORG     0000H\n        JB      P3.3,NHA\n        INC     32H                     ; thêm một tick giữ\n        MOV     A,32H\n        CLR     C\n        SUBB    A,#14H                  ; CY = 0 khi 32H >= 20\n        JC      XONG\n        MOV     30H,#00H                ; xóa số đếm\n        SJMP    XONG\nNHA:    MOV     32H,#00H\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":55,"0x32":19},"pins":{"P3":247}},"expect":{"iram":{"0x30":0,"0x32":20}}},{"setup":{"iram":{"0x30":55,"0x32":0},"pins":{"P3":255}},"expect":{"iram":{"0x30":55,"0x32":0}}},{"setup":{"iram":{"0x30":55,"0x32":5},"pins":{"P3":255}},"expect":{"iram":{"0x30":55,"0x32":0}}},{"setup":{"iram":{"0x30":55,"0x32":0},"pins":{"P3":247}},"expect":{"iram":{"0x30":55,"0x32":1}}},{"setup":{"iram":{"0x30":5,"0x32":20},"pins":{"P3":247}},"expect":{"iram":{"0x30":5,"0x32":20}}},{"setup":{"iram":{"0x30":153,"0x32":18},"pins":{"P3":247}},"expect":{"iram":{"0x30":153,"0x32":19}}},{"setup":{"iram":{"0x30":5,"0x32":20},"pins":{"P3":255}},"expect":{"iram":{"0x30":5,"0x32":0}}},{"setup":{"iram":{"0x30":153,"0x32":20},"pins":{"P3":247}},"expect":{"iram":{"0x30":153,"0x32":20}}}]},"hints":["Nhánh đầu: JB P3.3 tới đoạn ghi 32H = 00H.","Đang bấm: đọc 32H vào A, so với 14H bằng CJNE; bằng thì nhảy thẳng tới cuối (bão hòa).","Sau khi tăng, chỉ đúng lần vừa chạm ngưỡng mới xóa số đếm; các lần sau đã bão hòa nên không tới đó."],"why":"Bộ đếm giữ lâu phải bão hòa ở ngưỡng, nếu không mỗi tick sau ngưỡng lại xóa (code mẫu: so “≥ 20” nên bộ thử 5 xóa mất 05 sản phẩm vừa đếm). Xóa đúng một lần ở bước vượt ngưỡng chính là sự kiện “giữ lâu”, cùng kiểu với sự kiện nhấn của Bài 22."},{"t":"Một tick đầy đủ, ≤ 16 chu kỳ","d":"<p>Một tick của bộ đếm theo cách lọc “lịch sử 8 mẫu”: ô <code>33H<\/code> là lịch sử mẫu K1 (bit 0 = mẫu mới nhất, 1 = bấm). Mẫu mới m = 1 nếu chân <code>P3.2<\/code> = 0. Lịch sử mới H = (<code>33H<\/code> dịch trái 1 bit, bỏ bit 7) OR m; ghi H vào <code>33H<\/code>. Nếu H = <code>0FH<\/code> (4 mẫu nhả rồi 4 mẫu bấm) thì có sự kiện nhấn: tăng <code>30H<\/code> theo BCD (99 → 00). Cuối cùng <code>P1<\/code> = NOT <code>30H<\/code>. Yêu cầu: không quá <b>16 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>, ở nhánh dài nhất) và không quá <b>26 byte<\/b>.<\/p><p>Ví dụ: <code>33H = 07H<\/code>, <code>30H = 05H<\/code>, K1 bấm → <code>33H = 0FH<\/code>, <code>30H = 06H<\/code>, <code>P1 = F9H<\/code>. Code mẫu đúng nhưng nhánh có sự kiện tốn 18 chu kỳ.<\/p>","start":"        ORG     0000H\n        MOV     A,33H\n        CLR     C\n        RLC     A                       ; dịch lịch sử, bit 0 = 0\n        JB      P3.2,NHA\n        ORL     A,#01H                  ; đang bấm: bit 0 = 1\nNHA:    MOV     33H,A\n        CJNE    A,#0FH,XUAT\n        MOV     A,30H\n        ADD     A,#01H\n        DA      A\n        MOV     30H,A\nXUAT:   MOV     A,30H\n        CPL     A\n        MOV     P1,A\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":5,"0x33":7},"pins":{"P3":251}},"expect":{"iram":{"0x30":6,"0x33":15},"ports":{"P1":249}}},{"setup":{"iram":{"0x30":5,"0x33":7},"pins":{"P3":255}},"expect":{"iram":{"0x30":5,"0x33":14},"ports":{"P1":250}}},{"setup":{"iram":{"0x30":5,"0x33":15},"pins":{"P3":251}},"expect":{"iram":{"0x30":5,"0x33":31},"ports":{"P1":250}}},{"setup":{"iram":{"0x30":9,"0x33":135},"pins":{"P3":251}},"expect":{"iram":{"0x30":16,"0x33":15},"ports":{"P1":239}}},{"setup":{"iram":{"0x30":153,"0x33":3},"pins":{"P3":251}},"expect":{"iram":{"0x30":153,"0x33":7},"ports":{"P1":102}}},{"setup":{"iram":{"0x30":153,"0x33":7},"pins":{"P3":251}},"expect":{"iram":{"0x30":0,"0x33":15},"ports":{"P1":255}}},{"setup":{"iram":{"0x30":66,"0x33":247},"pins":{"P3":251}},"expect":{"iram":{"0x30":66,"0x33":239},"ports":{"P1":189}}}],"maxCyc":16,"maxBytes":26},"hints":["Code mẫu tạo bit mới bằng JB + ORL (3 chu kỳ khi bấm). Có thể đưa mẫu thẳng vào cờ C rồi để lệnh xoay qua cờ nhớ đẩy nó vào bit 0.","Đọc chân vào C, đảo C (bấm = 1), rồi xoay A trái qua CY: bit 7 cũ rơi vào CY, bit 0 nhận mẫu mới.","“Vừa ổn định ở mức bấm” là một giá trị cụ thể của byte lịch sử: tìm giá trị đó, so một lần, nhánh không có sự kiện đi thẳng tới phần xuất LED."],"why":"Lệnh xoay qua cờ nhớ vừa dịch lịch sử vừa đưa mẫu mới vào trong một chu kỳ, thay cho nhánh JB + ORL. Lịch sử 8 mẫu là một bộ lọc khác của Bài 22: H = 0FH chỉ xuất hiện một lần sau 4 mẫu bấm liên tiếp tiếp nối 4 mẫu nhả, nên giữ nút không đếm lặp và dội ngắn hơn 4 tick bị bỏ qua. Lời giải: 14 lệnh, 16 chu kỳ ở nhánh có sự kiện, 25 byte."}]);

makeQuiz("quiz24","score24",[{"q": "A = 39H (BCD). Sau ADD A,#01H rồi DA A, A bằng bao nhiêu?", "o": ["3AH", "4AH", "34H", "40H"], "a": 3, "e": "39H + 01H = 3AH; nửa thấp AH > 9 nên DA cộng 06H → 40H. 3AH là kết quả nếu quên DA A."}, {"q": "Vì sao không nên dùng INC A rồi DA A để tăng một số BCD?", "o": ["INC A không chạy được trên 8051", "INC không đặt AC, CY nên DA A dùng cờ còn sót của lệnh trước", "DA A chỉ dùng được với thanh ghi B", "INC A làm hỏng ô 30H"], "a": 1, "e": "DA A hiệu chỉnh dựa trên AC và CY của phép cộng vừa rồi. INC không đổi hai cờ này, nên một CY = 1 còn sót có thể làm DA cộng thêm 60H (ví dụ 5: 16H thành 76H)."}, {"q": "Bộ đếm giữ lâu so điều kiện “R4 ≥ 20 thì xóa số đếm”. Người vận hành giữ K2 thêm 1 s sau khi đã xóa, trong lúc đó có 3 sản phẩm đi qua. Số đếm cuối là bao nhiêu?", "o": ["00 — mỗi tick sau ngưỡng lại xóa", "03", "20", "Không xác định"], "a": 0, "e": "Điều kiện “≥ 20” đúng ở mọi tick sau ngưỡng nên số đếm bị xóa liên tục, 3 sản phẩm mất. Bộ đếm phải bão hòa và chỉ xóa khi vừa đạt ngưỡng."}, {"q": "Tick 0,5 ms, cần giữ K2 liên tục 20 tick để xóa. Thời gian giữ tối thiểu xấp xỉ bao nhiêu?", "o": ["20 ms", "40 ms", "10 ms", "0,5 ms"], "a": 2, "e": "20 × 0,5 ms = 10 ms. Đây là giá trị để chạy nhanh trong trình mô phỏng; sản phẩm thật chọn thời gian giữ cỡ giây (tick lớn hơn hoặc ngưỡng lớn hơn)."}, {"q": "Lịch sử mẫu 8 bit (bit 0 mới nhất, 1 = bấm) vừa thành 0FH. Ý nghĩa và hành động đúng?", "o": ["Nút đang giữ lâu: cộng 1 mỗi tick", "4 mẫu nhả rồi 4 mẫu bấm liên tiếp: một sự kiện nhấn, cộng 1", "Nút đang dội: bỏ qua", "4 mẫu bấm rồi 4 mẫu nhả: sự kiện thả"], "a": 1, "e": "0000 1111B: 4 mẫu cũ là nhả, 4 mẫu mới là bấm. Giá trị này chỉ xuất hiện đúng một lần cho mỗi lần bấm ổn định (tick sau đã là 1FH), nên cộng đúng một lần."}]);

fillSnips();
